package console

// Golden dump for the Rust port: the SQL generated by the console for many
// inputs, as single-line SQL. Only runs when AKVORADO_GOLDEN_OUT is set:
//
//	AKVORADO_GOLDEN_OUT=$PWD/tests/golden/testdata/console-sql.json \
//	  go test ./console -run TestGoldenDump -count=1

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"maps"
	"math/rand/v2"
	"net/http"
	"net/http/httptest"
	"os"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/AfterShip/clickhouse-sql-parser/parser"
	"github.com/ClickHouse/clickhouse-go/v2/lib/driver"
	"go.uber.org/mock/gomock"

	"akvorado/common/schema"
	sb "akvorado/common/sqlbuilder"
	"akvorado/console/query"
)

// singleLine renders a statement on a single line.
func singleLine(t *testing.T, sql string) string {
	t.Helper()
	statements, err := parser.NewParser(sql).ParseStmts()
	if err != nil {
		t.Fatalf("cannot parse SQL:\n%s\n%+v", sql, err)
	}
	if len(statements) != 1 {
		t.Fatalf("got %d statements", len(statements))
	}
	return parser.Format(statements[0])
}

type goldenResolution struct {
	Table         string `json:"table"`
	Interval      uint64 `json:"interval"`
	TableInterval uint64 `json:"table_interval"`
}

type goldenGraph struct {
	Kind           string           `json:"kind"`
	Resolution     goldenResolution `json:"resolution"`
	Start          time.Time        `json:"start"`
	End            time.Time        `json:"end"`
	Dimensions     []string         `json:"dimensions"`
	Filter         string           `json:"filter"`
	Limit          int              `json:"limit"`
	LimitType      string           `json:"limit_type"`
	TruncateV4     int              `json:"truncate_v4"`
	TruncateV6     int              `json:"truncate_v6"`
	Units          string           `json:"units"`
	Points         uint             `json:"points"`
	Bidirectional  bool             `json:"bidirectional"`
	PreviousPeriod bool             `json:"previous_period"`
	MainTable      bool             `json:"main_table_required"`
	Axes           []string         `json:"axes"`
	Union          string           `json:"union"`
}

type goldenTables struct {
	Tables   []goldenTable `json:"tables"`
	Start    time.Time     `json:"start"`
	End      time.Time     `json:"end"`
	Points   uint          `json:"points"`
	MainOnly bool          `json:"main_table_required"`
	Table    string        `json:"table"`
	Interval uint64        `json:"interval"`
	// Resolution applied to the range
	TableInterval uint64    `json:"table_interval"`
	RStart        time.Time `json:"r_start"`
	REnd          time.Time `json:"r_end"`
	Offset        uint64    `json:"offset"`
}

type goldenTable struct {
	Name       string    `json:"name"`
	Resolution uint64    `json:"resolution"`
	Oldest     time.Time `json:"oldest"`
}

func TestGoldenDump(t *testing.T) {
	out := os.Getenv("AKVORADO_GOLDEN_OUT")
	if out == "" {
		t.Skip("AKVORADO_GOLDEN_OUT not set")
	}
	all := schema.NewMock(t).EnableAllColumns()
	sch := all

	// Column selectors.
	selects := map[string]string{}
	for _, column := range all.Columns() {
		qc := query.NewColumn(column.Name)
		if qc.Validate(all) != nil {
			continue
		}
		selects[column.Name] = qc.ToSQLSelect(all, "default").String()
	}

	resolutions := []resolution{
		{Table: "flows", Interval: 60, TableInterval: time.Second},
		{Table: "flows_1m0s", Interval: 60, TableInterval: time.Minute},
		{Table: "flows_5m0s", Interval: 900, TableInterval: 5 * time.Minute},
	}
	dimensionSets := [][]string{
		{},
		{"SrcAS"},
		{"ExporterName", "InIfProvider"},
		{"SrcAddr", "DstAddr"},
		{"SrcPort", "Proto", "DstPort"},
		{"DstCommunities", "SrcMAC", "EType", "InIfBoundary", "DstASPath", "SrcNetPrefix"},
	}
	filters := []string{"", "InIfBoundary = external", "SrcPort = 80 AND DstCountry = 'FR'"}
	ranges := [][2]time.Time{
		{time.Date(2022, 4, 10, 15, 45, 10, 0, time.UTC), time.Date(2022, 4, 11, 15, 45, 10, 0, time.UTC)},
		{time.Date(2020, 2, 10, 15, 4, 0, 0, time.UTC), time.Date(2020, 7, 25, 17, 34, 0, 0, time.UTC)},
		{time.Date(2023, 1, 1, 0, 0, 7, 0, time.UTC), time.Date(2023, 1, 1, 1, 30, 0, 0, time.UTC)},
	}
	type truncation struct{ v4, v6 int }
	truncations := []truncation{{0, 0}, {24, 48}, {24, 120}, {0, 64}, {32, 128}}

	graphs := []goldenGraph{}
	add := func(kind string, res resolution, common graphCommonHandlerInput, points uint, bidi, prev bool) {
		var queries []*sb.Query
		var mainTable bool
		switch kind {
		case "line":
			input := graphLineHandlerInput{graphCommonHandlerInput: common, Points: points,
				Bidirectional: bidi, PreviousPeriod: prev}
			queries = input.toSQL(res)
			mainTable = input.resolveContext().MainTableRequired
		case "sankey":
			input := graphSankeyHandlerInput{graphCommonHandlerInput: common, Bidirectional: bidi}
			queries = input.toSQL(res)
			mainTable = input.resolveContext().MainTableRequired
		}
		g := goldenGraph{
			Kind: kind,
			Resolution: goldenResolution{res.Table, res.Interval,
				uint64(res.TableInterval.Seconds())},
			Start: common.Start, End: common.End,
			Dimensions: []string{}, Filter: common.Filter.String(),
			Limit: common.Limit, LimitType: common.LimitType,
			TruncateV4: common.TruncateAddrV4, TruncateV6: common.TruncateAddrV6,
			Units: common.Units, Points: points,
			Bidirectional: bidi, PreviousPeriod: prev, MainTable: mainTable,
		}
		for _, d := range common.Dimensions {
			g.Dimensions = append(g.Dimensions, d.String())
		}
		for _, q := range queries {
			g.Axes = append(g.Axes, singleLine(t, q.String()))
		}
		// unionAll modifies the first query, render again.
		switch kind {
		case "line":
			input := graphLineHandlerInput{graphCommonHandlerInput: common, Points: points,
				Bidirectional: bidi, PreviousPeriod: prev}
			g.Union = singleLine(t, unionAll(input.toSQL(res)))
		case "sankey":
			input := graphSankeyHandlerInput{graphCommonHandlerInput: common, Bidirectional: bidi}
			g.Union = singleLine(t, unionAll(input.toSQL(res)))
		}
		graphs = append(graphs, g)
	}
	common := func(dims []string, filter string, rng [2]time.Time) graphCommonHandlerInput {
		qcs := []query.Column{}
		for _, d := range dims {
			qcs = append(qcs, query.NewColumn(d))
		}
		if err := query.Columns(qcs).Validate(sch); err != nil {
			t.Fatalf("Validate(%v) error: %v", dims, err)
		}
		qf := query.NewFilter(filter)
		if err := qf.Validate(sch, "default"); err != nil {
			t.Fatalf("Validate(%q) error: %v", filter, err)
		}
		return graphCommonHandlerInput{
			schema: sch, database: "default",
			Start: rng[0], End: rng[1],
			Dimensions: qcs, Filter: qf, Limit: 10, LimitType: "avg", Units: "l3bps",
		}
	}

	for _, kind := range []string{"line", "sankey"} {
		for _, dims := range dimensionSets {
			if kind == "sankey" && len(dims) == 0 {
				continue
			}
			for _, filter := range filters {
				for _, res := range resolutions {
					for _, limitType := range []string{"avg", "max", "last"} {
						for _, bidi := range []bool{false, true} {
							c := common(dims, filter, ranges[0])
							c.LimitType = limitType
							add(kind, res, c, 100, bidi, kind == "line" && bidi)
						}
					}
				}
			}
			// Units, limits, truncation and ranges, on fewer combinations.
			for _, units := range []string{"fps", "pps", "l3bps", "l2bps", "inl2%", "outl2%"} {
				c := common(dims, "InIfBoundary = external", ranges[0])
				c.Units = units
				add(kind, resolutions[0], c, 100, true, false)
			}
			for _, limit := range []int{0, 1, 50} {
				c := common(dims, "", ranges[0])
				c.Limit = limit
				add(kind, resolutions[0], c, 100, false, false)
				add(kind, resolutions[2], c, 100, false, false)
			}
			for _, tr := range truncations {
				c := common(dims, "", ranges[0])
				c.TruncateAddrV4, c.TruncateAddrV6 = tr.v4, tr.v6
				add(kind, resolutions[1], c, 100, false, false)
			}
			if kind == "line" {
				for _, rng := range ranges {
					for _, bidi := range []bool{false, true} {
						c := common(dims, "SrcAS = 1", rng)
						add(kind, resolutions[0], c, 200, bidi, true)
						add(kind, resolutions[1], c, 7, bidi, true)
					}
				}
			}
		}
	}

	// Table selection.
	tableSets := [][]goldenTable{
		{{"flows", 0, time.Time{}}},
		{
			{"flows", 0, time.Date(2022, 4, 10, 0, 0, 0, 0, time.UTC)},
			{"flows_1m0s", 60, time.Date(2022, 3, 1, 0, 0, 0, 0, time.UTC)},
			{"flows_5m0s", 300, time.Date(2021, 1, 1, 0, 0, 0, 0, time.UTC)},
		},
		{
			{"flows", 0, time.Date(2022, 4, 11, 15, 0, 0, 0, time.UTC)},
			{"flows_1m0s", 60, time.Date(2022, 4, 11, 0, 0, 0, 0, time.UTC)},
			{"flows_1h0m0s", 3600, time.Date(2022, 4, 10, 18, 0, 0, 0, time.UTC)},
		},
		{
			{"flows_5m0s", 300, time.Date(2022, 1, 1, 0, 0, 0, 0, time.UTC)},
			{"flows", 0, time.Date(2022, 4, 1, 0, 0, 0, 0, time.UTC)},
			{"flows_1m0s", 60, time.Date(2022, 4, 1, 0, 0, 0, 0, time.UTC)},
		},
	}
	tables := []goldenTables{}
	c := &Component{}
	for _, set := range tableSets {
		c.flowsTables = nil
		for _, ft := range set {
			c.flowsTables = append(c.flowsTables, flowsTable{
				ft.Name, time.Duration(ft.Resolution) * time.Second, ft.Oldest})
		}
		for _, rng := range append(ranges, [2]time.Time{
			time.Date(2022, 4, 11, 15, 40, 3, 0, time.UTC),
			time.Date(2022, 4, 11, 15, 45, 3, 0, time.UTC),
		}) {
			for _, points := range []uint{5, 20, 100, 200, 2000} {
				for _, mainOnly := range []bool{false, true} {
					ic := inputContext{Start: rng[0], End: rng[1], Points: points, MainTableRequired: mainOnly}
					res := c.resolve(ic)
					r := res.forRange(rng[0], rng[1])
					table, interval, _ := c.computeTableAndInterval(ic)
					_ = table
					tables = append(tables, goldenTables{
						Tables: set, Start: rng[0], End: rng[1], Points: points, MainOnly: mainOnly,
						Table: res.Table, Interval: res.Interval,
						TableInterval: uint64(interval.Seconds()),
						RStart:        r.Start, REnd: r.End, Offset: r.Offset,
					})
				}
			}
		}
	}

	// Widgets, through the mocked connection.
	widgets := map[string]string{}
	for _, config := range []struct {
		name   string
		config func() Configuration
	}{
		{"default", DefaultConfiguration},
		{"no-filter", func() Configuration {
			config := DefaultConfiguration()
			config.HomepageTopWidgetsFilter = query.NewFilter("")
			config.HomepageGraphFilter = query.NewFilter("")
			config.HomepageGraphTimeRange = time.Hour
			return config
		}},
		{"main-filter", func() Configuration {
			config := DefaultConfiguration()
			config.HomepageTopWidgetsFilter = query.NewFilter("SrcPort = 443 AND InIfBoundary = external")
			config.HomepageGraphFilter = query.NewFilter("DstPort = 80")
			config.HomepageGraphTimeRange = 7 * 24 * time.Hour
			return config
		}},
	} {
		comp, _, mockConn, mockClock := NewMock(t, config.config())
		mockClock.Set(time.Date(2022, 4, 11, 15, 45, 10, 0, time.UTC))
		var captured string
		mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).
			DoAndReturn(func(_ context.Context, _ any, q string, _ ...any) error {
				captured = q
				return errors.New("captured")
			}).AnyTimes()
		mockConn.EXPECT().Query(gomock.Any(), gomock.Any()).
			DoAndReturn(func(_ context.Context, q string, _ ...any) (driver.Rows, error) {
				captured = q
				return nil, errors.New("captured")
			}).AnyTimes()
		run := func(name string, handler func()) {
			captured = ""
			handler()
			if captured != "" {
				widgets[fmt.Sprintf("%s/%s", config.name, name)] = singleLine(t, captured)
			}
		}
		for _, widget := range HomepageTopWidgetValues() {
			name := widget.String()
			run("top/"+name, func() { callHandler(comp.widgetTopHandlerFunc, "/widget/top/{name}", "/widget/top/"+name) })
		}
		run("graph", func() { callHandler(comp.widgetGraphHandlerFunc, "/widget/graph", "/widget/graph") })
		run("flow-last", func() { callHandler(comp.widgetFlowLastHandlerFunc, "/widget/flow-last", "/widget/flow-last") })
		if config.name != "default" {
			continue
		}
		for _, column := range []string{
			"DstCommunities", "SrcAS", "dstas", "Dst1stAS",
			"DstASPath", "SrcPort", "dstport", "SrcNetName", "DstNetRole", "srcnettenant",
			"ICMPv4", "icmpv6", "ExporterName", "exportertenant", "InIfName", "OutIfDescription",
			"InIfConnectivity", "OutIfProvider",
		} {
			for _, prefix := range []string{"", "a'b"} {
				for _, limit := range []int{0, 20, 5} {
					body := map[string]any{"what": "value", "column": column, "prefix": prefix}
					if limit > 0 {
						body["limit"] = limit
					}
					payload, _ := json.Marshal(body)
					run(fmt.Sprintf("complete/%s/%s/%d", column, prefix, limit), func() {
						mux := http.NewServeMux()
						mux.HandleFunc("/complete", comp.filterCompleteHandlerFunc)
						req := httptest.NewRequest(http.MethodPost, "/complete", bytes.NewReader(payload))
						req.Header.Set("Content-Type", "application/json")
						mux.ServeHTTP(httptest.NewRecorder(), req)
					})
				}
			}
		}
	}

	data, err := json.MarshalIndent(map[string]any{
		"selects": selects,
		"graphs":  graphs,
		"tables":  tables,
		"widgets": widgets,
	}, "", " ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("%d graphs, %d tables, %d widgets", len(graphs), len(tables), len(widgets))
}

// callHandler runs a handler with a matching path pattern.
func callHandler(h http.HandlerFunc, pattern, path string) {
	mux := http.NewServeMux()
	mux.HandleFunc(pattern, h)
	mux.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest(http.MethodGet, path, nil))
}

// Rows as the handlers scan them (aliases, so they are assignable).
type goldenLineRow = struct {
	Axis       uint8     `ch:"axis"`
	Time       time.Time `ch:"time"`
	Xps        float64   `ch:"xps"`
	Dimensions []string  `ch:"dimensions"`
}

type goldenSankeyRow = struct {
	Axis       uint8    `ch:"axis"`
	Xps        float64  `ch:"xps"`
	Dimensions []string `ch:"dimensions"`
}

type goldenOutput struct {
	Kind   string          `json:"kind"`
	Input  map[string]any  `json:"input"`
	Rows   any             `json:"rows"`
	Status int             `json:"status"`
	Output json.RawMessage `json:"output"`
}

// TestGoldenDumpOutput feeds random results to the line and sankey handlers
// and records what they answer.
func TestGoldenDumpOutput(t *testing.T) {
	out := os.Getenv("AKVORADO_GOLDEN_OUT")
	if out == "" {
		t.Skip("AKVORADO_GOLDEN_OUT not set")
	}
	out = strings.Replace(out, "console-sql.json", "console-output.json", 1)
	comp, _, mockConn, _ := NewMock(t, DefaultConfiguration())
	rng := rand.New(rand.NewPCG(1, 2))
	base := time.Date(2009, time.November, 10, 23, 0, 0, 0, time.UTC)
	values := [][]string{
		{"router1", "router2", "router3", "router4"},
		{"provider1", "provider2", "provider3"},
		{"1299: Telia", "174: Cogent", "3356: Level3"},
	}
	columns := []string{"ExporterName", "InIfProvider", "SrcAS"}
	unitsList := []string{"l3bps", "pps", "inl2%", "fps"}
	limitTypes := []string{"avg", "max", "last"}
	spans := []time.Duration{time.Hour, 6 * time.Hour, 3 * 24 * time.Hour, 20 * 24 * time.Hour, 90 * 24 * time.Hour}
	outputs := []goldenOutput{}

	post := func(handler http.HandlerFunc, input map[string]any) (int, json.RawMessage) {
		payload, _ := json.Marshal(input)
		mux := http.NewServeMux()
		mux.HandleFunc("/h", handler)
		req := httptest.NewRequest(http.MethodPost, "/h", bytes.NewReader(payload))
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		return rec.Code, json.RawMessage(rec.Body.Bytes())
	}

	for i := range 300 {
		nDims := rng.IntN(4)
		dims := columns[:nDims]
		axesSets := [][]uint8{{1}, {1, 2}, {1, 3}, {1, 2, 3, 4}}
		axes := axesSets[rng.IntN(len(axesSets))]
		nTimes := 2 + rng.IntN(5)
		rows := []goldenLineRow{}
		for _, axis := range axes {
			times := nTimes
			if axis != 1 {
				times = 1 + rng.IntN(nTimes)
			}
			for ti := range times {
				when := base.Add(time.Duration(ti) * time.Minute)
				combos := 1 + rng.IntN(5)
				seen := map[string]bool{}
				for range combos {
					d := []string{}
					if axis < 3 {
						for di := range nDims {
							d = append(d, values[di][rng.IntN(len(values[di]))])
						}
					}
					if nDims > 0 && rng.IntN(6) == 0 {
						d = make([]string, nDims)
						for di := range d {
							d[di] = "Other"
						}
					}
					key := fmt.Sprint(d)
					if seen[key] {
						continue
					}
					seen[key] = true
					rows = append(rows, goldenLineRow{axis, when, rng.Float64() * 1e6, d})
				}
				if axis == 1 && len(seen) == 0 {
					rows = append(rows, goldenLineRow{axis, when, rng.Float64() * 1e6, nil})
				}
			}
		}
		span := spans[rng.IntN(len(spans))]
		start := time.Date(2022, 4, 10, 15, 45, 10, 0, time.UTC)
		input := map[string]any{
			"start": start, "end": start.Add(span),
			"points": 100, "limit": 10, "limitType": limitTypes[rng.IntN(3)],
			"dimensions": dims, "filter": "", "units": unitsList[rng.IntN(len(unitsList))],
			"bidirectional": slices.Contains(axes, 2), "previous-period": slices.Contains(axes, 3),
		}
		mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		status, output := post(comp.graphLineHandlerFunc, input)
		if status != 200 {
			t.Fatalf("line case %d: status %d: %s", i, status, output)
		}
		outputs = append(outputs, goldenOutput{"line", input, rows, status, output})
	}

	for i := range 200 {
		nDims := 1 + rng.IntN(3)
		dims := columns[:nDims]
		bidi := rng.IntN(2) == 0
		rows := []goldenSankeyRow{}
		axes := []uint8{1}
		if bidi {
			axes = append(axes, 2)
		}
		for _, axis := range axes {
			seen := map[string]bool{}
			for range 1 + rng.IntN(8) {
				d := []string{}
				for di := range nDims {
					if rng.IntN(5) == 0 {
						d = append(d, "Other")
					} else {
						d = append(d, values[di][rng.IntN(len(values[di]))])
					}
				}
				key := fmt.Sprint(d)
				if seen[key] {
					continue
				}
				seen[key] = true
				rows = append(rows, goldenSankeyRow{axis, float64(rng.IntN(1000000)) + rng.Float64(), d})
			}
		}
		start := time.Date(2022, 4, 10, 15, 45, 10, 0, time.UTC)
		input := map[string]any{
			"start": start, "end": start.Add(time.Hour),
			"limit": 10, "limitType": limitTypes[rng.IntN(3)],
			"dimensions": dims, "filter": "", "units": unitsList[rng.IntN(len(unitsList))],
			"bidirectional": bidi,
		}
		mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		status, output := post(comp.graphSankeyHandlerFunc, input)
		if status != 200 {
			t.Fatalf("sankey case %d: status %d: %s", i, status, output)
		}
		outputs = append(outputs, goldenOutput{"sankey", input, rows, status, output})
	}

	data, err := json.MarshalIndent(outputs, "", " ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatal(err)
	}
	t.Logf("%d outputs", len(outputs))
}

// TestGoldenDumpDocs renders each document as the web interface asks for it.
func TestGoldenDumpDocs(t *testing.T) {
	out := os.Getenv("AKVORADO_GOLDEN_OUT")
	if out == "" {
		t.Skip("AKVORADO_GOLDEN_OUT not set")
	}
	out = strings.Replace(out, "console-sql.json", "docs.json", 1)
	comp, _, _, _ := NewMock(t, DefaultConfiguration())
	docs := map[string]map[string]any{}
	markdown := map[string]string{}
	entries, err := os.ReadDir("data/docs")
	if err != nil {
		t.Fatal(err)
	}
	names := []string{"operations", "notexist"}
	for _, entry := range entries {
		if m := internalLinkRegexp.FindStringSubmatch(entry.Name()); m != nil {
			names = append(names, m[3])
		}
	}
	for _, name := range names {
		mux := http.NewServeMux()
		mux.HandleFunc("/docs/{name}", comp.docsHandlerFunc)
		req := httptest.NewRequest(http.MethodGet, "/docs/"+name, nil)
		req.Header.Set("Accept", "application/json")
		rec := httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		docs[name] = map[string]any{"status": rec.Code, "body": rec.Body.String()}
		req = httptest.NewRequest(http.MethodGet, "/docs/"+name, nil)
		rec = httptest.NewRecorder()
		mux.ServeHTTP(rec, req)
		markdown[name] = rec.Body.String()
	}
	index := string(comp.documentIndex())
	data, _ := json.MarshalIndent(map[string]any{"docs": docs, "markdown": markdown, "index": index}, "", " ")
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatal(err)
	}
}

// goldenHTTPCase is a request to the console API, with the rows the mocked
// ClickHouse answers.
type goldenHTTPCase struct {
	Method   string            `json:"method"`
	URL      string            `json:"url"`
	Headers  map[string]string `json:"headers,omitempty"`
	Body     any               `json:"body,omitempty"`
	RowsKind string            `json:"rows_kind,omitempty"`
	Rows     []map[string]any  `json:"rows,omitempty"`
	// Answer of the Go version.
	Status      int               `json:"status"`
	RespHeaders map[string]string `json:"resp_headers"`
	RespBody    string            `json:"resp_body"`
}

func TestGoldenDumpHTTP(t *testing.T) {
	out := os.Getenv("AKVORADO_GOLDEN_OUT")
	if out == "" {
		t.Skip("AKVORADO_GOLDEN_OUT not set")
	}
	out = strings.Replace(out, "console-sql.json", "console-http.json", 1)
	_, h, mockConn, mockClock := NewMock(t, DefaultConfiguration())
	mockClock.Set(time.Date(2022, 4, 11, 15, 45, 10, 0, time.UTC))
	base := time.Date(2009, time.November, 10, 23, 0, 0, 0, time.UTC)
	start := time.Date(2022, 4, 10, 15, 45, 10, 0, time.UTC)
	end := start.Add(24 * time.Hour)
	labels := func(l ...string) []map[string]any {
		rows := []map[string]any{}
		for _, v := range l {
			rows = append(rows, map[string]any{"label": v})
		}
		return rows
	}
	labelDetails := func(l ...string) []map[string]any {
		rows := []map[string]any{}
		for i := 0; i < len(l); i += 2 {
			rows = append(rows, map[string]any{"label": l[i], "detail": l[i+1]})
		}
		return rows
	}
	lineRows := []map[string]any{
		{"axis": 1, "time": base, "xps": 1000.5, "dimensions": []string{"router1", "provider1"}},
		{"axis": 1, "time": base, "xps": 2000, "dimensions": []string{"router1", "provider2"}},
		{"axis": 1, "time": base, "xps": 1900, "dimensions": []string{"Other", "Other"}},
		{"axis": 1, "time": base.Add(time.Minute), "xps": 500, "dimensions": []string{"router1", "provider1"}},
		{"axis": 1, "time": base.Add(time.Minute), "xps": 5000, "dimensions": []string{"router1", "provider2"}},
		{"axis": 1, "time": base.Add(2 * time.Minute), "xps": 100, "dimensions": []string{"router1", "provider1"}},
		{"axis": 2, "time": base, "xps": 101, "dimensions": []string{"router1", "provider1"}},
		{"axis": 2, "time": base.Add(time.Minute), "xps": 50, "dimensions": []string{"router1", "provider1"}},
		{"axis": 3, "time": base, "xps": 8000, "dimensions": []string{}},
		{"axis": 3, "time": base.Add(time.Minute), "xps": 6000, "dimensions": []string{}},
	}
	sankeyRows := []map[string]any{
		{"axis": 1, "xps": 9677, "dimensions": []string{"AS100", "Other", "France"}},
		{"axis": 1, "xps": 9472, "dimensions": []string{"AS300", "provider1", "Other"}},
		{"axis": 1, "xps": 7593, "dimensions": []string{"AS300", "provider2", "France"}},
		{"axis": 2, "xps": 6006, "dimensions": []string{"AS100", "provider1", "Other"}},
	}
	line := func(extra map[string]any) map[string]any {
		body := map[string]any{
			"start": start, "end": end, "points": 100, "limit": 10, "limitType": "avg",
			"dimensions": []string{"ExporterName", "InIfProvider"}, "filter": "DstCountry = 'FR'",
			"units": "l3bps", "bidirectional": true, "previous-period": true,
		}
		maps.Copy(body, extra)
		for k, v := range extra {
			if v == nil {
				delete(body, k)
			}
		}
		return body
	}
	sankey := func(extra map[string]any) map[string]any {
		body := map[string]any{
			"start": start, "end": end, "limit": 10, "limitType": "avg",
			"dimensions": []string{"SrcAS", "InIfProvider", "ExporterName"}, "filter": "",
			"units": "l3bps", "bidirectional": true,
		}
		maps.Copy(body, extra)
		return body
	}
	user := map[string]string{"Remote-User": "alfred"}
	cases := []goldenHTTPCase{
		{Method: "GET", URL: "/api/v0/console/configuration"},
		{Method: "POST", URL: "/api/v0/console/filter/validate", Body: map[string]any{"filter": `InIfName = "Gi0/0/0/1"`}},
		{Method: "POST", URL: "/api/v0/console/filter/validate", Body: map[string]any{"filter": `InIfName = "`}},
		{Method: "POST", URL: "/api/v0/console/filter/validate", Body: map[string]any{"filter": `SrcPort > 80 AND <> 1`}},
		{Method: "POST", URL: "/api/v0/console/filter/validate", Body: map[string]any{"filter": `  `}},
		{Method: "POST", URL: "/api/v0/console/filter/validate", Body: map[string]any{"filter": `Unknown = 1`}},
		{Method: "POST", URL: "/api/v0/console/filter/validate"},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "column", "prefix": "dSt"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "column", "prefix": ""}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator", "column": "SrcAS"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator", "column": "InIfBoundary"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator", "column": "Proto"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator", "column": "DstASPath"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator", "column": "Unknown"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "operator"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "other", "column": "x"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "inifboundary", "prefix": "EX"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "proto", "prefix": "I"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "etype"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "FlowDirection", "prefix": "e"}},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "exporterName", "prefix": "th2-"},
			RowsKind: "label", Rows: labels("th2-router1", "th2-router2", "th2-router3")},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "srcnetName", "prefix": "c"},
			RowsKind: "label", Rows: labels("customer-1", "customer-2")},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "dstAS", "prefix": "goog", "operator": "="},
			RowsKind: "label-detail", Rows: labelDetails("AS15169", "Google", "AS36040", "Google")},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "dstAS", "prefix": "srca", "operator": "="},
			RowsKind: "label-detail", Rows: labelDetails()},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "dstcommunities", "prefix": "6540"},
			RowsKind: "label-detail", Rows: labelDetails("65401:10", "community", "65402:200:100", "large community")},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "srcPort", "prefix": "http", "limit": 5},
			RowsKind: "label-detail", Rows: labelDetails("443", "https", "80", "http")},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "SrcPort", "operator": ">", "prefix": "dst"},
			RowsKind: "label-detail", Rows: labelDetails()},
		{Method: "POST", URL: "/api/v0/console/filter/complete", Body: map[string]any{"what": "value", "column": "ExporterName", "operator": "!=", "prefix": ""},
			RowsKind: "label", Rows: labels("edge1")},
		{Method: "POST", URL: "/api/v0/console/graph/reverse", Body: map[string]any{"dimensions": []string{"SrcAS", "InIfProvider", "ExporterName"}, "filter": "SrcAS = 1 AND InIfName = 'x'"}},
		{Method: "POST", URL: "/api/v0/console/graph/reverse", Body: map[string]any{"filter": "SrcAS = "}},
		{Method: "POST", URL: "/api/v0/console/graph/reverse", Body: map[string]any{"dimensions": []string{"Nope"}}},
		{Method: "POST", URL: "/api/v0/console/graph/table-interval", Body: map[string]any{"start": start, "end": end, "points": 100}},
		{Method: "POST", URL: "/api/v0/console/graph/table-interval", Body: map[string]any{"start": start, "end": end}},
		{Method: "POST", URL: "/api/v0/console/graph/table-interval", Body: map[string]any{"start": end, "end": start, "points": 3}},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(nil), RowsKind: "line", Rows: lineRows},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"limitType": "max", "units": "inl2%"}), RowsKind: "line", Rows: lineRows},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"units": nil})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"units": "bps"})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"points": 3})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"points": nil})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"limit": 100})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"limit": 0})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"limitType": "min"})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"dimensions": []string{"Nope"}})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"filter": "SrcAS ="})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"end": start})},
		{Method: "POST", URL: "/api/v0/console/graph/line", Body: line(map[string]any{"truncate-v4": 40})},
		{Method: "POST", URL: "/api/v0/console/graph/line"},
		{Method: "POST", URL: "/api/v0/console/graph/sankey", Body: sankey(nil), RowsKind: "sankey", Rows: sankeyRows},
		{Method: "POST", URL: "/api/v0/console/graph/sankey", Body: sankey(map[string]any{"dimensions": []string{}})},
		{Method: "GET", URL: "/api/v0/console/widget/top/src-as", RowsKind: "top",
			Rows: []map[string]any{{"Name": "2906: Netflix", "Percent": 12.5}, {"Name": "36040: Youtube", "Percent": 10}}},
		{Method: "GET", URL: "/api/v0/console/widget/top/notexist"},
		{Method: "GET", URL: "/api/v0/console/widget/exporters", RowsKind: "exporters",
			Rows: []map[string]any{{"ExporterName": "exporter1"}, {"ExporterName": "exporter2"}}},
		{Method: "GET", URL: "/api/v0/console/widget/graph", RowsKind: "graph",
			Rows: []map[string]any{{"Time": base, "Gbps": 1.5}, {"Time": base.Add(time.Minute), "Gbps": 2.25}}},
		{Method: "GET", URL: "/api/v0/console/filter/saved", Headers: user},
		{Method: "POST", URL: "/api/v0/console/filter/saved", Headers: user, Body: map[string]any{"description": "mine", "content": "SrcAS = 1"}},
		{Method: "POST", URL: "/api/v0/console/filter/saved", Headers: map[string]string{"Remote-User": "bob"}, Body: map[string]any{"description": "shared", "content": "SrcAS = 2", "shared": true}},
		{Method: "POST", URL: "/api/v0/console/filter/saved", Headers: user, Body: map[string]any{"content": "SrcAS = 1"}},
		{Method: "GET", URL: "/api/v0/console/filter/saved", Headers: user},
		{Method: "DELETE", URL: "/api/v0/console/filter/saved/abc", Headers: user},
		{Method: "DELETE", URL: "/api/v0/console/filter/saved/2", Headers: user},
		{Method: "DELETE", URL: "/api/v0/console/filter/saved/1", Headers: user},
		{Method: "GET", URL: "/api/v0/console/filter/saved", Headers: user},
		{Method: "GET", URL: "/api/v0/console/user/info"},
		{Method: "GET", URL: "/api/v0/console/user/info", Headers: map[string]string{"Remote-User": "alfred", "Remote-Name": "Alfred Pennyworth", "Remote-Email": "alfred@example.com"}},
		{Method: "GET", URL: "/api/v0/console/user/info", Headers: map[string]string{"Remote-User": "alfred", "Remote-Email": "nope"}},
		{Method: "GET", URL: "/api/v0/console/user/avatar", Headers: user},
		{Method: "GET", URL: "/api/v0/console/user/avatar", Headers: map[string]string{"Remote-User": "alfred", "If-None-Match": `"b2e72a535032fa89"`}},
		{Method: "GET", URL: "/api/v0/console/docs/intro", Headers: map[string]string{"Accept": "application/json"}},
		{Method: "GET", URL: "/api/v0/console/docs/operations"},
		{Method: "GET", URL: "/api/v0/console/docs/notexist"},
	}
	client := &http.Client{}
	for i := range cases {
		c := &cases[i]
		switch c.RowsKind {
		case "label":
			rows := []struct {
				Label string `ch:"label"`
			}{}
			for _, r := range c.Rows {
				rows = append(rows, struct {
					Label string `ch:"label"`
				}{r["label"].(string)})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "label-detail":
			rows := []struct {
				Label  string `ch:"label"`
				Detail string `ch:"detail"`
			}{}
			for _, r := range c.Rows {
				rows = append(rows, struct {
					Label  string `ch:"label"`
					Detail string `ch:"detail"`
				}{r["label"].(string), r["detail"].(string)})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "line":
			rows := []goldenLineRow{}
			for _, r := range c.Rows {
				rows = append(rows, goldenLineRow{uint8(r["axis"].(int)), r["time"].(time.Time), toFloat(r["xps"]), r["dimensions"].([]string)})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "sankey":
			rows := []goldenSankeyRow{}
			for _, r := range c.Rows {
				rows = append(rows, goldenSankeyRow{uint8(r["axis"].(int)), toFloat(r["xps"]), r["dimensions"].([]string)})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "top":
			rows := []topResult{}
			for _, r := range c.Rows {
				rows = append(rows, topResult{r["Name"].(string), toFloat(r["Percent"])})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "exporters":
			rows := []struct{ ExporterName string }{}
			for _, r := range c.Rows {
				rows = append(rows, struct{ ExporterName string }{r["ExporterName"].(string)})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		case "graph":
			rows := []struct {
				Time time.Time `json:"t"`
				Gbps float64   `json:"gbps"`
			}{}
			for _, r := range c.Rows {
				rows = append(rows, struct {
					Time time.Time `json:"t"`
					Gbps float64   `json:"gbps"`
				}{r["Time"].(time.Time), toFloat(r["Gbps"])})
			}
			mockConn.EXPECT().Select(gomock.Any(), gomock.Any(), gomock.Any()).SetArg(1, rows).Return(nil)
		}
		var body io.Reader
		if c.Body != nil {
			payload, _ := json.Marshal(c.Body)
			body = bytes.NewReader(payload)
		}
		req, _ := http.NewRequest(c.Method, fmt.Sprintf("http://%s%s", h.LocalAddr(), c.URL), body)
		req.Header.Set("Content-Type", "application/json")
		for k, v := range c.Headers {
			req.Header.Set(k, v)
		}
		resp, err := client.Do(req)
		if err != nil {
			t.Fatalf("%s %s: %v", c.Method, c.URL, err)
		}
		data, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		c.Status = resp.StatusCode
		c.RespHeaders = map[string]string{}
		for _, k := range []string{"Content-Type", "Etag", "Vary", "Cache-Control"} {
			if v := resp.Header.Get(k); v != "" {
				c.RespHeaders[k] = v
			}
		}
		if strings.HasPrefix(resp.Header.Get("Content-Type"), "image/") {
			c.RespBody = fmt.Sprintf("<%d bytes>", len(data))
		} else {
			c.RespBody = string(data)
		}
	}
	data, _ := json.MarshalIndent(cases, "", " ")
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatal(err)
	}
}

func toFloat(v any) float64 {
	switch v := v.(type) {
	case int:
		return float64(v)
	case float64:
		return v
	}
	panic("not a number")
}
